WITH unpacked AS (SELECT id, plan, effective_from, tier_limits, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT id, effective_from, entry_price, LEAD(avg_tier_price) OVER w_ordered AS next_avg_tier_price, LAG(avg_tier_price) OVER w_ordered AS prev_avg_tier_price, LEAD(entry_price) OVER w_ordered AS next_entry_price, LAG(entry_price) OVER w_ordered AS prev_entry_price, ROW_NUMBER() OVER w_ordered AS row_seq, AVG(avg_tier_price) OVER w_recent AS avg_tier_price_avg_3_prior FROM unpacked WHERE entry_price < 11 WINDOW w_ordered AS (PARTITION BY plan ORDER BY avg_tier_price, id), w_recent AS (PARTITION BY plan ORDER BY entry_price, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING)
